create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text,avatar_url text,plan text not null default 'free' check(plan in('free','pro')),credits integer not null default 20 check(credits>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.generations(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,tool_name text not null,input_summary text not null,output jsonb not null,metadata jsonb not null default '{}',credits_used integer not null check(credits_used>0),created_at timestamptz not null default now());
create table public.documents(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,file_name text not null,file_path text not null,file_type text not null,file_size integer not null check(file_size>0),created_at timestamptz not null default now());
create table public.usage_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,tool_name text not null,credits_used integer not null,status text not null check(status in('reserved','success','refunded','failed')),created_at timestamptz not null default now());
create index generations_user_created_idx on public.generations(user_id,created_at desc);create index generations_user_tool_idx on public.generations(user_id,tool_name);create index documents_user_created_idx on public.documents(user_id,created_at desc);create index usage_events_user_created_idx on public.usage_events(user_id,created_at desc);
alter table public.profiles enable row level security;alter table public.generations enable row level security;alter table public.documents enable row level security;alter table public.usage_events enable row level security;
create policy "own profile select" on public.profiles for select using(auth.uid()=id);create policy "own profile update" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);create policy "own generations" on public.generations for select using(auth.uid()=user_id);create policy "own generations insert" on public.generations for insert with check(auth.uid()=user_id);create policy "own generations delete" on public.generations for delete using(auth.uid()=user_id);create policy "own documents" on public.documents for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own usage" on public.usage_events for select using(auth.uid()=user_id);create policy "own usage insert" on public.usage_events for insert with check(auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email);return new;end;$$;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.reserve_credits(p_tool_name text,p_credits integer) returns boolean language plpgsql security definer set search_path=public as $$declare changed integer;begin update profiles set credits=credits-p_credits,updated_at=now() where id=auth.uid() and credits>=p_credits;get diagnostics changed=row_count;if changed=1 then insert into usage_events(user_id,tool_name,credits_used,status)values(auth.uid(),p_tool_name,p_credits,'reserved');return true;end if;return false;end;$$;
create or replace function public.refund_credits(p_tool_name text,p_credits integer) returns boolean language plpgsql security definer set search_path=public as $$begin update profiles set credits=credits+p_credits,updated_at=now() where id=auth.uid();insert into usage_events(user_id,tool_name,credits_used,status)values(auth.uid(),p_tool_name,p_credits,'refunded');return found;end;$$;
revoke all on function public.reserve_credits(text,integer) from public;revoke all on function public.refund_credits(text,integer) from public;grant execute on function public.reserve_credits(text,integer) to authenticated;grant execute on function public.refund_credits(text,integer) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('documents','documents',false,5242880,array['application/pdf','text/plain']) on conflict(id)do nothing;create policy "own storage documents" on storage.objects for all to authenticated using(bucket_id='documents' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='documents' and (storage.foldername(name))[1]=auth.uid()::text);
